"use client";

import { useState } from "react";
import Link from "next/link";
import {
  ArrowDownLeft,
  ArrowUpRight,
  Banknote,
  BarChart3,
  CalendarDays,
  ChevronRight,
  CircleDollarSign,
  CreditCard,
  FileText,
  Landmark,
  Plus,
  Receipt,
  RefreshCw,
  Search,
  Wallet,
} from "lucide-react";

import PageHeader from "@/components/ui/PageHeader";
import Button from "@/components/ui/Button";
import EmptyState from "@/components/ui/EmptyState";

import "./FinanceDashboard.css";

const financeModules = [
  {
    title: "Accounts",
    description: "Manage financial accounts and account classifications.",
    href: "/finance/accounts",
    icon: Landmark,
  },
  {
    title: "Income",
    description: "Record and manage incoming financial transactions.",
    href: "/finance/income",
    icon: ArrowDownLeft,
  },
  {
    title: "Expenses",
    description: "Track operational and business expenses.",
    href: "/finance/expenses",
    icon: ArrowUpRight,
  },
  {
    title: "Invoices",
    description: "Create, manage and track customer invoices.",
    href: "/finance/invoices",
    icon: FileText,
  },
  {
    title: "Payments",
    description: "Record received and outgoing payments.",
    href: "/finance/payments",
    icon: CreditCard,
  },
  {
    title: "Receivables",
    description: "Monitor outstanding customer balances.",
    href: "/finance/receivables",
    icon: Wallet,
  },
  {
    title: "Payables",
    description: "Monitor supplier and business obligations.",
    href: "/finance/payables",
    icon: Receipt,
  },
  {
    title: "Cash & Bank",
    description: "Manage cash accounts and bank transactions.",
    href: "/finance/cash-bank",
    icon: Banknote,
  },
  {
    title: "Transactions",
    description: "Review the complete financial transaction ledger.",
    href: "/finance/transactions",
    icon: RefreshCw,
  },
  {
    title: "Financial Reports",
    description: "Review financial reporting and analysis.",
    href: "/finance/reports",
    icon: BarChart3,
  },
];

export default function FinancePage() {
  const [search, setSearch] = useState("");
  const [period, setPeriod] = useState("current-month");

  const filteredModules = financeModules.filter((module) => {
    const query = search.trim().toLowerCase();

    if (!query) {
      return true;
    }

    return (
      module.title.toLowerCase().includes(query) ||
      module.description.toLowerCase().includes(query)
    );
  });

  const handleRefresh = () => {
    /*
      Backend refresh will be connected here.
      Keep the action available so the page is ready
      for API/data fetching later.
    */

    setSearch("");
    setPeriod("current-month");
  };

  return (
    <div className="finance-page">
      <PageHeader
        eyebrow="FINANCE"
        title="Finance Overview"
        description="Centralized financial management for accounts, transactions, invoices, payments and reporting."
        action={
          <Button
            variant="primary"
            size="md"
            icon={Plus}
            onClick={() => {
              window.location.href = "/finance/transactions";
            }}
          >
            New Transaction
          </Button>
        }
      />

      <section className="finance-toolbar">
        <div className="finance-search">
          <Search
            size={17}
            strokeWidth={1.8}
            aria-hidden="true"
          />

          <input
            type="search"
            value={search}
            onChange={(event) => setSearch(event.target.value)}
            placeholder="Search finance modules..."
            aria-label="Search finance modules"
          />
        </div>

        <div className="finance-toolbar__actions">
          <div className="finance-period">
            <CalendarDays
              size={16}
              strokeWidth={1.8}
              aria-hidden="true"
            />

            <select
              value={period}
              onChange={(event) => setPeriod(event.target.value)}
              aria-label="Financial reporting period"
            >
              <option value="current-month">
                Current Month
              </option>

              <option value="previous-month">
                Previous Month
              </option>

              <option value="current-quarter">
                Current Quarter
              </option>

              <option value="current-year">
                Current Year
              </option>

              <option value="custom">
                Custom Period
              </option>
            </select>
          </div>

          <Button
            variant="secondary"
            size="md"
            icon={RefreshCw}
            onClick={handleRefresh}
          >
            Refresh
          </Button>
        </div>
      </section>

      <section className="finance-kpis">
        <FinanceKpi
          icon={CircleDollarSign}
          label="Total Income"
          value="—"
          description="No financial data"
        />

        <FinanceKpi
          icon={ArrowUpRight}
          label="Total Expenses"
          value="—"
          description="No financial data"
        />

        <FinanceKpi
          icon={Wallet}
          label="Receivables"
          value="—"
          description="No financial data"
        />

        <FinanceKpi
          icon={Receipt}
          label="Payables"
          value="—"
          description="No financial data"
        />
      </section>

      <section className="finance-main-grid">
        <div className="finance-panel finance-panel--modules">
          <div className="finance-panel__header">
            <div>
              <span className="finance-panel__eyebrow">
                FINANCIAL OPERATIONS
              </span>

              <h2>Finance Modules</h2>
            </div>

            <span className="finance-panel__count">
              {filteredModules.length}
            </span>
          </div>

          <div className="finance-module-grid">
            {filteredModules.map((module) => (
              <FinanceModuleCard
                key={module.href}
                {...module}
              />
            ))}
          </div>

          {filteredModules.length === 0 && (
            <EmptyState
              icon={Search}
              title="No modules found"
              description="Try another search term."
              size="small"
            />
          )}
        </div>

        <aside className="finance-panel finance-panel--activity">
          <div className="finance-panel__header">
            <div>
              <span className="finance-panel__eyebrow">
                ACTIVITY
              </span>

              <h2>Recent Transactions</h2>
            </div>
          </div>

          <EmptyState
            icon={Receipt}
            title="No transactions yet"
            description="Financial transactions will appear here once connected to the backend."
            size="small"
          />

          <Link
            href="/finance/transactions"
            className="finance-panel__link"
          >
            View transaction ledger
            <ChevronRight
              size={15}
              strokeWidth={2}
              aria-hidden="true"
            />
          </Link>
        </aside>
      </section>

      <section className="finance-panel finance-panel--reports">
        <div className="finance-panel__header">
          <div>
            <span className="finance-panel__eyebrow">
              REPORTING
            </span>

            <h2>Financial Reporting</h2>

            <p>
              Access financial statements, transaction analysis,
              receivables, payables and account reporting.
            </p>
          </div>

          <Link
            href="/finance/reports"
            className="finance-view-link"
          >
            Open Reports
            <ChevronRight
              size={15}
              strokeWidth={2}
              aria-hidden="true"
            />
          </Link>
        </div>

        <div className="finance-report-state">
          <BarChart3
            size={24}
            strokeWidth={1.7}
            aria-hidden="true"
          />

          <div>
            <strong>Reporting data unavailable</strong>

            <span>
              Connect the finance backend to populate financial
              statements and analytics.
            </span>
          </div>
        </div>
      </section>
    </div>
  );
}

function FinanceKpi({
  icon: Icon,
  label,
  value,
  description,
}) {
  return (
    <article className="finance-kpi">
      <div className="finance-kpi__icon">
        <Icon
          size={19}
          strokeWidth={1.8}
          aria-hidden="true"
        />
      </div>

      <div className="finance-kpi__content">
        <span>{label}</span>

        <strong>{value}</strong>

        <small>{description}</small>
      </div>
    </article>
  );
}

function FinanceModuleCard({
  title,
  description,
  href,
  icon: Icon,
}) {
  return (
    <Link
      href={href}
      className="finance-module-card"
    >
      <div className="finance-module-card__icon">
        <Icon
          size={19}
          strokeWidth={1.8}
          aria-hidden="true"
        />
      </div>

      <div className="finance-module-card__content">
        <h3>{title}</h3>

        <p>{description}</p>
      </div>

      <ChevronRight
        className="finance-module-card__arrow"
        size={17}
        strokeWidth={1.8}
        aria-hidden="true"
      />
    </Link>
  );
}

"use client";

import { useMemo, useState } from "react";
import {
  ArrowDownToLine,
  ArrowUpFromLine,
  CheckCircle2,
  Clock3,
  Download,
  FileText,
  Plus,
  Search,
  SlidersHorizontal,
  XCircle,
} from "lucide-react";

import PageHeader from "@/components/ui/PageHeader";
import Button from "@/components/ui/Button";

import "./Adjustments.css";

const STATUS_OPTIONS = [
  { value: "all", label: "All Status" },
  { value: "draft", label: "Draft" },
  { value: "pending", label: "Pending Approval" },
  { value: "approved", label: "Approved" },
  { value: "posted", label: "Posted" },
  { value: "cancelled", label: "Cancelled" },
];

const STATUS_CONFIG = {
  draft: {
    label: "Draft",
    icon: FileText,
    tone: "neutral",
  },
  pending: {
    label: "Pending Approval",
    icon: Clock3,
    tone: "warning",
  },
  approved: {
    label: "Approved",
    icon: CheckCircle2,
    tone: "info",
  },
  posted: {
    label: "Posted",
    icon: CheckCircle2,
    tone: "success",
  },
  cancelled: {
    label: "Cancelled",
    icon: XCircle,
    tone: "danger",
  },
};

export default function AdjustmentsPage() {
  const [search, setSearch] = useState("");
  const [status, setStatus] = useState("all");
  const [loading] = useState(false);

  /*
   * Backend-ready.
   * Adjustment records will be supplied by the API later.
   */
  const adjustments = [];

  const filteredAdjustments = useMemo(() => {
    const query = search.trim().toLowerCase();

    return adjustments.filter((adjustment) => {
      const matchesSearch =
        !query ||
        adjustment.reference?.toLowerCase().includes(query) ||
        adjustment.product?.toLowerCase().includes(query) ||
        adjustment.sku?.toLowerCase().includes(query) ||
        adjustment.warehouse?.toLowerCase().includes(query);

      const matchesStatus =
        status === "all" || adjustment.status === status;

      return matchesSearch && matchesStatus;
    });
  }, [adjustments, search, status]);

  const increaseCount = adjustments.filter(
    (item) => item.direction === "increase"
  ).length;

  const decreaseCount = adjustments.filter(
    (item) => item.direction === "decrease"
  ).length;

  const pendingCount = adjustments.filter(
    (item) => item.status === "pending"
  ).length;

  const postedCount = adjustments.filter(
    (item) => item.status === "posted"
  ).length;

  const hasFilters = search || status !== "all";

  const resetFilters = () => {
    setSearch("");
    setStatus("all");
  };

  const handleNewAdjustment = () => {
    /* Backend integration pending. */
  };

  const handleExport = () => {
    /* Backend integration pending. */
  };

  return (
    <main className="inventory-adjustments">
      <PageHeader
        eyebrow="Inventory"
        title="Stock Adjustments"
        description="Correct inventory differences with controlled quantity changes, reasons, approvals, and audit history."
        action={
          <div className="inventory-adjustments__header-actions">
            <Button
              variant="secondary"
              onClick={handleExport}
              disabled={
                loading ||
                filteredAdjustments.length === 0
              }
            >
              <Download size={15} />
              Export
            </Button>

            <Button
              variant="primary"
              onClick={handleNewAdjustment}
            >
              <Plus size={15} />
              New Adjustment
            </Button>
          </div>
        }
      />

      <div className="inventory-adjustments__content">
        {/* SUMMARY */}

        <section className="inventory-adjustments__summary">
          <div className="inventory-adjustments__summary-card">
            <div className="inventory-adjustments__summary-icon">
              <SlidersHorizontal size={18} />
            </div>

            <div>
              <span>Total Adjustments</span>
              <strong>{adjustments.length}</strong>
            </div>
          </div>

          <div className="inventory-adjustments__summary-card">
            <div className="inventory-adjustments__summary-icon inventory-adjustments__summary-icon--success">
              <ArrowUpFromLine size={18} />
            </div>

            <div>
              <span>Stock Increases</span>
              <strong>{increaseCount}</strong>
            </div>
          </div>

          <div className="inventory-adjustments__summary-card">
            <div className="inventory-adjustments__summary-icon inventory-adjustments__summary-icon--danger">
              <ArrowDownToLine size={18} />
            </div>

            <div>
              <span>Stock Decreases</span>
              <strong>{decreaseCount}</strong>
            </div>
          </div>

          <div className="inventory-adjustments__summary-card">
            <div className="inventory-adjustments__summary-icon inventory-adjustments__summary-icon--warning">
              <Clock3 size={18} />
            </div>

            <div>
              <span>Pending Approval</span>
              <strong>{pendingCount}</strong>
            </div>
          </div>

          <div className="inventory-adjustments__summary-card">
            <div className="inventory-adjustments__summary-icon inventory-adjustments__summary-icon--info">
              <CheckCircle2 size={18} />
            </div>

            <div>
              <span>Posted</span>
              <strong>{postedCount}</strong>
            </div>
          </div>
        </section>

        {/* FILTERS */}

        <section className="inventory-adjustments__filters">
          <div className="inventory-adjustments__search">
            <Search size={16} />

            <input
              type="search"
              value={search}
              onChange={(event) =>
                setSearch(event.target.value)
              }
              placeholder="Search reference, product, SKU or warehouse..."
              aria-label="Search stock adjustments"
            />
          </div>

          <div className="inventory-adjustments__select">
            <select
              value={status}
              onChange={(event) =>
                setStatus(event.target.value)
              }
              aria-label="Filter adjustment status"
            >
              {STATUS_OPTIONS.map((option) => (
                <option
                  key={option.value}
                  value={option.value}
                >
                  {option.label}
                </option>
              ))}
            </select>
          </div>

          {hasFilters && (
            <button
              type="button"
              className="inventory-adjustments__reset"
              onClick={resetFilters}
            >
              Reset
            </button>
          )}
        </section>

        {/* TABLE */}

        <section className="inventory-adjustments__card">
          <div className="inventory-adjustments__card-header">
            <div>
              <span className="inventory-adjustments__eyebrow">
                Adjustment Register
              </span>

              <h2>Adjustment History</h2>
            </div>

            <span className="inventory-adjustments__count">
              {filteredAdjustments.length} records
            </span>
          </div>

          {loading ? (
            <div className="inventory-adjustments__loading">
              Loading adjustments...
            </div>
          ) : filteredAdjustments.length === 0 ? (
            <div className="inventory-adjustments__empty">
              <div className="inventory-adjustments__empty-icon">
                <SlidersHorizontal size={22} />
              </div>

              <h3>No stock adjustments yet</h3>

              <p>
                Inventory corrections will appear here when
                stock is adjusted because of physical counts,
                damage, loss, opening balances, or other
                approved reasons.
              </p>

              <Button
                variant="primary"
                onClick={handleNewAdjustment}
              >
                <Plus size={15} />
                New Adjustment
              </Button>
            </div>
          ) : (
            <div className="inventory-adjustments__table-wrap">
              <table className="inventory-adjustments__table">
                <thead>
                  <tr>
                    <th>Reference</th>
                    <th>Product</th>
                    <th>SKU</th>
                    <th>Warehouse</th>
                    <th>Direction</th>
                    <th>Quantity</th>
                    <th>Reason</th>
                    <th>Status</th>
                    <th>Created By</th>
                    <th>Date</th>
                  </tr>
                </thead>

                <tbody>
                  {filteredAdjustments.map((adjustment) => {
                    const config =
                      STATUS_CONFIG[adjustment.status] ||
                      STATUS_CONFIG.draft;

                    const Icon = config.icon;

                    const isIncrease =
                      adjustment.direction === "increase";

                    return (
                      <tr key={adjustment.id}>
                        <td>
                          <strong>
                            {adjustment.reference || "—"}
                          </strong>
                        </td>

                        <td>
                          {adjustment.product || "—"}
                        </td>

                        <td>
                          <span className="inventory-adjustments__sku">
                            {adjustment.sku || "—"}
                          </span>
                        </td>

                        <td>
                          {adjustment.warehouse || "—"}
                        </td>

                        <td>
                          <span
                            className={`inventory-adjustments__direction inventory-adjustments__direction--${
                              isIncrease
                                ? "increase"
                                : "decrease"
                            }`}
                          >
                            {isIncrease ? (
                              <ArrowUpFromLine size={13} />
                            ) : (
                              <ArrowDownToLine size={13} />
                            )}

                            {isIncrease
                              ? "Increase"
                              : "Decrease"}
                          </span>
                        </td>

                        <td>
                          <strong>
                            {adjustment.quantity ?? 0}
                          </strong>

                          {adjustment.unit && (
                            <span className="inventory-adjustments__unit">
                              {" "}
                              {adjustment.unit}
                            </span>
                          )}
                        </td>

                        <td>
                          {adjustment.reason || "—"}
                        </td>

                        <td>
                          <span
                            className={`inventory-adjustments__status inventory-adjustments__status--${config.tone}`}
                          >
                            <Icon size={13} />
                            {config.label}
                          </span>
                        </td>

                        <td>
                          {adjustment.createdBy || "—"}
                        </td>

                        <td>
                          {adjustment.createdAt || "—"}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </section>

        {/* ADJUSTMENT RULES */}

        <section className="inventory-adjustments__rules">
          <div className="inventory-adjustments__rules-header">
            <div>
              <span className="inventory-adjustments__eyebrow">
                Control Framework
              </span>

              <h2>Adjustment Controls</h2>
            </div>
          </div>

          <div className="inventory-adjustments__rules-grid">
            <div className="inventory-adjustments__rule">
              <span className="inventory-adjustments__rule-number">
                01
              </span>

              <div>
                <strong>Record the reason</strong>
                <p>
                  Every stock correction must have a
                  defined business reason.
                </p>
              </div>
            </div>

            <div className="inventory-adjustments__rule">
              <span className="inventory-adjustments__rule-number">
                02
              </span>

              <div>
                <strong>Verify physical stock</strong>
                <p>
                  Adjustments should reference an actual
                  count or documented variance.
                </p>
              </div>
            </div>

            <div className="inventory-adjustments__rule">
              <span className="inventory-adjustments__rule-number">
                03
              </span>

              <div>
                <strong>Approval before posting</strong>
                <p>
                  Controlled adjustments can require
                  approval before affecting stock.
                </p>
              </div>
            </div>

            <div className="inventory-adjustments__rule">
              <span className="inventory-adjustments__rule-number">
                04
              </span>

              <div>
                <strong>Keep the audit trail</strong>
                <p>
                  User, timestamp, quantity and reason
                  remain part of the adjustment history.
                </p>
              </div>
            </div>
          </div>
        </section>
      </div>
    </main>
  );
}

"use client";

import { useMemo, useState } from "react";
import {
  Archive,
  CalendarDays,
  CheckCircle2,
  Download,
  Package,
  Search,
  ShieldCheck,
  TriangleAlert,
  XCircle,
} from "lucide-react";

import PageHeader from "@/components/ui/PageHeader";
import Button from "@/components/ui/Button";

import "./BatchesLots.css";

const STATUS_OPTIONS = [
  { value: "all", label: "All Status" },
  { value: "active", label: "Active" },
  { value: "quarantine", label: "Quarantine" },
  { value: "expired", label: "Expired" },
  { value: "depleted", label: "Depleted" },
];

const STATUS_CONFIG = {
  active: {
    label: "Active",
    icon: CheckCircle2,
    tone: "success",
  },
  quarantine: {
    label: "Quarantine",
    icon: ShieldCheck,
    tone: "warning",
  },
  expired: {
    label: "Expired",
    icon: TriangleAlert,
    tone: "danger",
  },
  depleted: {
    label: "Depleted",
    icon: XCircle,
    tone: "neutral",
  },
};

export default function BatchesLotsPage() {
  const [search, setSearch] = useState("");
  const [status, setStatus] = useState("all");
  const [loading] = useState(false);

  /*
   * Backend-ready.
   * Batch and lot records will come from the API later.
   */
  const batches = [];

  const filteredBatches = useMemo(() => {
    const query = search.trim().toLowerCase();

    return batches.filter((batch) => {
      const matchesSearch =
        !query ||
        batch.batchNumber?.toLowerCase().includes(query) ||
        batch.lotNumber?.toLowerCase().includes(query) ||
        batch.product?.toLowerCase().includes(query) ||
        batch.sku?.toLowerCase().includes(query) ||
        batch.warehouse?.toLowerCase().includes(query);

      const matchesStatus =
        status === "all" || batch.status === status;

      return matchesSearch && matchesStatus;
    });
  }, [batches, search, status]);

  const activeCount = batches.filter(
    (batch) => batch.status === "active"
  ).length;

  const quarantineCount = batches.filter(
    (batch) => batch.status === "quarantine"
  ).length;

  const expiredCount = batches.filter(
    (batch) => batch.status === "expired"
  ).length;

  const totalQuantity = batches.reduce(
    (sum, batch) => sum + (batch.quantity || 0),
    0
  );

  const hasFilters = search || status !== "all";

  const resetFilters = () => {
    setSearch("");
    setStatus("all");
  };

  const handleExport = () => {
    /* Backend integration pending. */
  };

  const handleAddBatch = () => {
    /* Backend integration pending. */
  };

  return (
    <main className="inventory-batches">
      <PageHeader
        eyebrow="Inventory"
        title="Batches & Lots"
        description="Track inventory batches and lots across warehouses with complete traceability and stock status."
        action={
          <div className="inventory-batches__header-actions">
            <Button
              variant="secondary"
              onClick={handleExport}
              disabled={
                loading ||
                filteredBatches.length === 0
              }
            >
              <Download size={15} />
              Export
            </Button>

            <Button
              variant="primary"
              onClick={handleAddBatch}
            >
              <Package size={15} />
              Add Batch
            </Button>
          </div>
        }
      />

      <div className="inventory-batches__content">
        {/* SUMMARY */}

        <section className="inventory-batches__summary">
          <div className="inventory-batches__summary-card">
            <div className="inventory-batches__summary-icon">
              <Archive size={18} />
            </div>

            <div>
              <span>Total Batches</span>
              <strong>{batches.length}</strong>
            </div>
          </div>

          <div className="inventory-batches__summary-card">
            <div className="inventory-batches__summary-icon inventory-batches__summary-icon--success">
              <CheckCircle2 size={18} />
            </div>

            <div>
              <span>Active</span>
              <strong>{activeCount}</strong>
            </div>
          </div>

          <div className="inventory-batches__summary-card">
            <div className="inventory-batches__summary-icon inventory-batches__summary-icon--warning">
              <ShieldCheck size={18} />
            </div>

            <div>
              <span>Quarantine</span>
              <strong>{quarantineCount}</strong>
            </div>
          </div>

          <div className="inventory-batches__summary-card">
            <div className="inventory-batches__summary-icon inventory-batches__summary-icon--danger">
              <TriangleAlert size={18} />
            </div>

            <div>
              <span>Expired</span>
              <strong>{expiredCount}</strong>
            </div>
          </div>

          <div className="inventory-batches__summary-card">
            <div className="inventory-batches__summary-icon">
              <Package size={18} />
            </div>

            <div>
              <span>Total Quantity</span>
              <strong>{totalQuantity}</strong>
            </div>
          </div>
        </section>

        {/* FILTERS */}

        <section className="inventory-batches__filters">
          <div className="inventory-batches__search">
            <Search size={16} />

            <input
              type="search"
              value={search}
              onChange={(event) =>
                setSearch(event.target.value)
              }
              placeholder="Search batch, lot, product, SKU or warehouse..."
              aria-label="Search batches and lots"
            />
          </div>

          <div className="inventory-batches__select">
            <select
              value={status}
              onChange={(event) =>
                setStatus(event.target.value)
              }
              aria-label="Filter batch status"
            >
              {STATUS_OPTIONS.map((option) => (
                <option
                  key={option.value}
                  value={option.value}
                >
                  {option.label}
                </option>
              ))}
            </select>
          </div>

          {hasFilters && (
            <button
              type="button"
              className="inventory-batches__reset"
              onClick={resetFilters}
            >
              Reset
            </button>
          )}
        </section>

        {/* TABLE */}

        <section className="inventory-batches__card">
          <div className="inventory-batches__card-header">
            <div>
              <span className="inventory-batches__eyebrow">
                Traceability Register
              </span>

              <h2>Batch & Lot Inventory</h2>
            </div>

            <span className="inventory-batches__count">
              {filteredBatches.length} records
            </span>
          </div>

          {loading ? (
            <div className="inventory-batches__loading">
              Loading batches...
            </div>
          ) : filteredBatches.length === 0 ? (
            <div className="inventory-batches__empty">
              <div className="inventory-batches__empty-icon">
                <Archive size={22} />
              </div>

              <h3>No batches or lots yet</h3>

              <p>
                Batch and lot records will appear here once
                inventory is received and assigned a traceable
                batch or lot number.
              </p>

              <Button
                variant="primary"
                onClick={handleAddBatch}
              >
                <Package size={15} />
                Add Batch
              </Button>
            </div>
          ) : (
            <div className="inventory-batches__table-wrap">
              <table className="inventory-batches__table">
                <thead>
                  <tr>
                    <th>Batch / Lot</th>
                    <th>Product</th>
                    <th>SKU</th>
                    <th>Warehouse</th>
                    <th>Quantity</th>
                    <th>Manufactured</th>
                    <th>Expiry</th>
                    <th>Status</th>
                  </tr>
                </thead>

                <tbody>
                  {filteredBatches.map((batch) => {
                    const config =
                      STATUS_CONFIG[batch.status] ||
                      STATUS_CONFIG.active;

                    const Icon = config.icon;

                    return (
                      <tr key={batch.id}>
                        <td>
                          <div className="inventory-batches__batch">
                            <strong>
                              {batch.batchNumber || "—"}
                            </strong>

                            {batch.lotNumber && (
                              <span>
                                Lot {batch.lotNumber}
                              </span>
                            )}
                          </div>
                        </td>

                        <td>
                          {batch.product || "—"}
                        </td>

                        <td>
                          <span className="inventory-batches__sku">
                            {batch.sku || "—"}
                          </span>
                        </td>

                        <td>
                          {batch.warehouse || "—"}
                        </td>

                        <td>
                          <strong>
                            {batch.quantity ?? 0}
                          </strong>

                          {batch.unit && (
                            <span className="inventory-batches__unit">
                              {" "}
                              {batch.unit}
                            </span>
                          )}
                        </td>

                        <td>
                          <div className="inventory-batches__date">
                            <CalendarDays size={13} />
                            {batch.manufacturedAt || "—"}
                          </div>
                        </td>

                        <td>
                          <div className="inventory-batches__date">
                            <CalendarDays size={13} />
                            {batch.expiryAt || "—"}
                          </div>
                        </td>

                        <td>
                          <span
                            className={`inventory-batches__status inventory-batches__status--${config.tone}`}
                          >
                            <Icon size={13} />
                            {config.label}
                          </span>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </section>

        {/* TRACEABILITY */}

        <section className="inventory-batches__traceability">
          <div className="inventory-batches__traceability-header">
            <div>
              <span className="inventory-batches__eyebrow">
                Traceability
              </span>

              <h2>Batch Lifecycle</h2>
            </div>
          </div>

          <div className="inventory-batches__traceability-grid">
            <div className="inventory-batches__trace-step">
              <span>01</span>

              <div>
                <strong>Receive</strong>
                <p>
                  Assign the incoming material to a batch
                  or supplier lot.
                </p>
              </div>
            </div>

            <div className="inventory-batches__trace-step">
              <span>02</span>

              <div>
                <strong>Store</strong>
                <p>
                  Track the batch against its warehouse
                  location and stock quantity.
                </p>
              </div>
            </div>

            <div className="inventory-batches__trace-step">
              <span>03</span>

              <div>
                <strong>Move</strong>
                <p>
                  Preserve batch identity during warehouse
                  transfers and issues.
                </p>
              </div>
            </div>

            <div className="inventory-batches__trace-step">
              <span>04</span>

              <div>
                <strong>Consume</strong>
                <p>
                  Link material usage to production,
                  dispatch or other stock transactions.
                </p>
              </div>
            </div>
          </div>
        </section>
      </div>
    </main>
  );
}

"use client";

import { useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import {
  ArrowDownToLine,
  ArrowLeftRight,
  ArrowUpFromLine,
  Download,
  Filter,
  RefreshCw,
  Search,
  SlidersHorizontal,
} from "lucide-react";

import PageHeader from "@/components/ui/PageHeader";
import Button from "@/components/ui/Button";

import "./Movements.css";

const TYPE_OPTIONS = [
  { value: "all", label: "All Movements" },
  { value: "receipt", label: "Receipt" },
  { value: "issue", label: "Issue" },
  { value: "transfer", label: "Transfer" },
  { value: "adjustment", label: "Adjustment" },
];

const DIRECTION_OPTIONS = [
  { value: "all", label: "All Directions" },
  { value: "in", label: "Stock In" },
  { value: "out", label: "Stock Out" },
];

const MOVEMENT_CONFIG = {
  receipt: {
    label: "Receipt",
    icon: ArrowDownToLine,
    tone: "success",
  },
  issue: {
    label: "Issue",
    icon: ArrowUpFromLine,
    tone: "danger",
  },
  transfer: {
    label: "Transfer",
    icon: ArrowLeftRight,
    tone: "info",
  },
  adjustment: {
    label: "Adjustment",
    icon: SlidersHorizontal,
    tone: "warning",
  },
};

export default function MovementsPage() {
  const router = useRouter();

  const [search, setSearch] = useState("");
  const [type, setType] = useState("all");
  const [direction, setDirection] = useState("all");
  const [loading] = useState(false);

  /*
   * Backend-ready.
   * No mock movement records.
   */
  const movements = [];

  const filteredMovements = useMemo(() => {
    const searchValue = search.trim().toLowerCase();

    return movements.filter((movement) => {
      const matchesSearch =
        !searchValue ||
        movement.reference
          ?.toLowerCase()
          .includes(searchValue) ||
        movement.productName
          ?.toLowerCase()
          .includes(searchValue) ||
        movement.sku
          ?.toLowerCase()
          .includes(searchValue) ||
        movement.warehouseName
          ?.toLowerCase()
          .includes(searchValue);

      const matchesType =
        type === "all" || movement.type === type;

      const matchesDirection =
        direction === "all" ||
        movement.direction === direction;

      return (
        matchesSearch &&
        matchesType &&
        matchesDirection
      );
    });
  }, [movements, search, type, direction]);

  const resetFilters = () => {
    setSearch("");
    setType("all");
    setDirection("all");
  };

  const handleExport = () => {
    /*
     * Real client-side CSV export of the currently filtered
     * movements. Backend-generated Excel/PDF exports will
     * replace this when the API is connected.
     */
    const rows = [
      [
        "Type", "Reference", "Product", "SKU", "Warehouse",
        "Direction", "Quantity", "Unit", "User", "Date",
      ],
      ...filteredMovements.map((movement) => [
        movement.typeLabel || movement.type,
        movement.reference || "",
        movement.productName || "",
        movement.sku || "",
        movement.warehouseName || "",
        movement.direction || "",
        movement.quantity ?? "",
        movement.unit || "",
        movement.userName || "",
        movement.createdAt || "",
      ]),
    ];

    const csv = rows
      .map((row) =>
        row.map((cell) => `"` + String(cell).replace(/"/g, `""`) + `"`).join(",")
      )
      .join("\n");

    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = "stock-movements-" + new Date().toISOString().slice(0, 10) + ".csv";
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleRefresh = () => {
    /*
     * API refetch will be connected later; filters reset is the
     * current frontend behavior.
     */
    resetFilters();
  };
  const hasFilters =
    search ||
    type !== "all" ||
    direction !== "all";

  return (
    <main className="inventory-movements">
      <PageHeader
        eyebrow="Inventory"
        title="Stock Movements"
        description="Track every inventory movement across warehouses, products, and stock operations."
        action={
          <div className="inventory-movements__header-actions">
            <Button
              variant="secondary"
              onClick={handleRefresh}
              disabled={loading}
            >
              <RefreshCw size={15} />
              Refresh
            </Button>

            <Button
              variant="secondary"
              onClick={handleExport}
              disabled={
                loading ||
                filteredMovements.length === 0
              }
            >
              <Download size={15} />
              Export
            </Button>
          </div>
        }
      />

      <div className="inventory-movements__content">
        {/* ------------------------------------------------
            SUMMARY
        ------------------------------------------------ */}

        <section className="inventory-movements__summary">
          <div className="inventory-movements__summary-card">
            <span>Total Movements</span>
            <strong>{movements.length}</strong>
          </div>

          <div className="inventory-movements__summary-card">
            <span>Stock In</span>
            <strong>
              {
                movements.filter(
                  (item) => item.direction === "in"
                ).length
              }
            </strong>
          </div>

          <div className="inventory-movements__summary-card">
            <span>Stock Out</span>
            <strong>
              {
                movements.filter(
                  (item) => item.direction === "out"
                ).length
              }
            </strong>
          </div>

          <div className="inventory-movements__summary-card">
            <span>Transfers</span>
            <strong>
              {
                movements.filter(
                  (item) => item.type === "transfer"
                ).length
              }
            </strong>
          </div>
        </section>

        {/* ------------------------------------------------
            FILTERS
        ------------------------------------------------ */}

        <section className="inventory-movements__filters">
          <div className="inventory-movements__search">
            <Search size={16} />

            <input
              type="search"
              value={search}
              onChange={(event) =>
                setSearch(event.target.value)
              }
              placeholder="Search reference, SKU, product..."
              aria-label="Search stock movements"
            />
          </div>

          <div className="inventory-movements__filter">
            <Filter size={15} />

            <select
              value={type}
              onChange={(event) =>
                setType(event.target.value)
              }
              aria-label="Filter movement type"
            >
              {TYPE_OPTIONS.map((option) => (
                <option
                  key={option.value}
                  value={option.value}
                >
                  {option.label}
                </option>
              ))}
            </select>
          </div>

          <div className="inventory-movements__filter">
            <SlidersHorizontal size={15} />

            <select
              value={direction}
              onChange={(event) =>
                setDirection(event.target.value)
              }
              aria-label="Filter movement direction"
            >
              {DIRECTION_OPTIONS.map((option) => (
                <option
                  key={option.value}
                  value={option.value}
                >
                  {option.label}
                </option>
              ))}
            </select>
          </div>

          {hasFilters && (
            <button
              type="button"
              className="inventory-movements__reset"
              onClick={resetFilters}
            >
              Reset
            </button>
          )}
        </section>

        {/* ------------------------------------------------
            MOVEMENT TABLE
        ------------------------------------------------ */}

        <section className="inventory-movements__card">
          <div className="inventory-movements__card-header">
            <div>
              <span className="inventory-movements__eyebrow">
                Stock Ledger
              </span>

              <h2>Movement History</h2>
            </div>

            <span className="inventory-movements__count">
              {filteredMovements.length} records
            </span>
          </div>

          {loading ? (
            <div className="inventory-movements__loading">
              <RefreshCw
                size={17}
                className="inventory-movements__spin"
              />
              Loading movements...
            </div>
          ) : filteredMovements.length === 0 ? (
            <div className="inventory-movements__empty">
              <div className="inventory-movements__empty-icon">
                <ArrowLeftRight size={21} />
              </div>

              <h3>No stock movements yet</h3>

              <p>
                Stock receipts, issues, transfers, and
                adjustments will appear here once inventory
                operations are recorded.
              </p>

              <Button
                variant="primary"
                onClick={() =>
                  router.push(
                    "/procurement/goods-receipts"
                  )
                }
              >
                Receive Stock
              </Button>
            </div>
          ) : (
            <div className="inventory-movements__table-wrap">
              <table className="inventory-movements__table">
                <thead>
                  <tr>
                    <th>Type</th>
                    <th>Reference</th>
                    <th>Product</th>
                    <th>Warehouse</th>
                    <th>Direction</th>
                    <th>Quantity</th>
                    <th>User</th>
                    <th>Date / Time</th>
                  </tr>
                </thead>

                <tbody>
                  {filteredMovements.map((movement) => {
                    const config =
                      MOVEMENT_CONFIG[movement.type] ||
                      MOVEMENT_CONFIG.adjustment;

                    const Icon = config.icon;

                    return (
                      <tr key={movement.id}>
                        <td>
                          <div className="inventory-movements__type">
                            <span
                              className={`inventory-movements__type-icon inventory-movements__type-icon--${config.tone}`}
                            >
                              <Icon size={15} />
                            </span>

                            <span>
                              {movement.typeLabel ||
                                config.label}
                            </span>
                          </div>
                        </td>

                        <td>
                          <strong>
                            {movement.reference || "—"}
                          </strong>
                        </td>

                        <td>
                          <div className="inventory-movements__product">
                            <strong>
                              {movement.productName || "—"}
                            </strong>

                            {movement.sku && (
                              <span>
                                {movement.sku}
                              </span>
                            )}
                          </div>
                        </td>

                        <td>
                          {movement.warehouseName || "—"}
                        </td>

                        <td>
                          <span
                            className={`inventory-movements__direction inventory-movements__direction--${movement.direction}`}
                          >
                            {movement.direction === "in"
                              ? "Stock In"
                              : movement.direction ===
                                "out"
                              ? "Stock Out"
                              : "—"}
                          </span>
                        </td>

                        <td>
                          <strong>
                            {movement.quantity ?? 0}
                          </strong>

                          {movement.unit && (
                            <span className="inventory-movements__unit">
                              {" "}
                              {movement.unit}
                            </span>
                          )}
                        </td>

                        <td>
                          {movement.userName || "—"}
                        </td>

                        <td>
                          {movement.createdAt || "—"}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </section>
      </div>
    </main>
  );
}

"use client";

import { useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import {
  Boxes,
  Download,
  Filter,
  Package,
  RefreshCw,
  Search,
  SlidersHorizontal,
  Warehouse,
} from "lucide-react";

import PageHeader from "@/components/ui/PageHeader";
import Button from "@/components/ui/Button";

import "./Stock.css";

const CATEGORY_OPTIONS = [
  { value: "all", label: "All Categories" },
  { value: "garments", label: "Garments" },
  { value: "fabrics", label: "Fabrics" },
  { value: "accessories", label: "Garment Accessories" },
];

const STOCK_STATUS_OPTIONS = [
  { value: "all", label: "All Status" },
  { value: "in-stock", label: "In Stock" },
  { value: "low", label: "Low Stock" },
  { value: "out-of-stock", label: "Out of Stock" },
];

export default function StockPage() {
  const router = useRouter();

  const [search, setSearch] = useState("");
  const [category, setCategory] = useState("all");
  const [status, setStatus] = useState("all");
  const [warehouse, setWarehouse] = useState("all");
  const [loading] = useState(false);

  /*
   * Backend-ready.
   *
   * Do not add mock inventory records here.
   * This array will later be populated by the inventory API.
   */
  const stockItems = [];

  const warehouses = [];

  const filteredItems = useMemo(() => {
    return stockItems.filter((item) => {
      const searchValue = search.trim().toLowerCase();

      const matchesSearch =
        !searchValue ||
        item.name?.toLowerCase().includes(searchValue) ||
        item.sku?.toLowerCase().includes(searchValue) ||
        item.productCode?.toLowerCase().includes(searchValue);

      const matchesCategory =
        category === "all" || item.category === category;

      const matchesStatus =
        status === "all" || item.status === status;

      const matchesWarehouse =
        warehouse === "all" || item.warehouseId === warehouse;

      return (
        matchesSearch &&
        matchesCategory &&
        matchesStatus &&
        matchesWarehouse
      );
    });
  }, [stockItems, search, category, status, warehouse]);

  const handleReset = () => {
    setSearch("");
    setCategory("all");
    setStatus("all");
    setWarehouse("all");
  };

  const handleExport = () => {
    /*
     * Export API will be connected later.
     */
    /* Backend integration pending. */
  };

  const hasFilters =
    search ||
    category !== "all" ||
    status !== "all" ||
    warehouse !== "all";

  return (
    <main className="inventory-stock">
      <PageHeader
        eyebrow="Inventory"
        title="Stock"
        description="View and monitor available stock across garments, fabrics, and garment accessories."
        action={
          <div className="inventory-stock__header-actions">
            <Button
              variant="secondary"
              onClick={handleExport}
              disabled={loading || filteredItems.length === 0}
            >
              <Download size={15} />
              Export
            </Button>

            <Button
              variant="primary"
              onClick={() =>
                router.push("/procurement/goods-receipts")
              }
            >
              <Package size={15} />
              Receive Stock
            </Button>
          </div>
        }
      />

      <div className="inventory-stock__content">
        {/* ------------------------------------------------
            SUMMARY
        ------------------------------------------------ */}

        <section className="inventory-stock__summary">
          <div className="inventory-stock__summary-card">
            <div className="inventory-stock__summary-icon">
              <Boxes size={18} />
            </div>

            <div>
              <span>Total Items</span>
              <strong>{stockItems.length}</strong>
            </div>
          </div>

          <div className="inventory-stock__summary-card">
            <div className="inventory-stock__summary-icon">
              <Warehouse size={18} />
            </div>

            <div>
              <span>Warehouses</span>
              <strong>{warehouses.length}</strong>
            </div>
          </div>

          <div className="inventory-stock__summary-card">
            <div className="inventory-stock__summary-icon">
              <Package size={18} />
            </div>

            <div>
              <span>Low Stock</span>
              <strong>
                {
                  stockItems.filter(
                    (item) => item.status === "low"
                  ).length
                }
              </strong>
            </div>
          </div>
        </section>

        {/* ------------------------------------------------
            FILTER BAR
        ------------------------------------------------ */}

        <section className="inventory-stock__filters">
          <div className="inventory-stock__search">
            <Search size={16} />

            <input
              type="search"
              value={search}
              onChange={(event) =>
                setSearch(event.target.value)
              }
              placeholder="Search SKU, product name..."
              aria-label="Search inventory stock"
            />
          </div>

          <div className="inventory-stock__filter">
            <Filter size={15} />

            <select
              value={category}
              onChange={(event) =>
                setCategory(event.target.value)
              }
              aria-label="Filter by category"
            >
              {CATEGORY_OPTIONS.map((option) => (
                <option
                  key={option.value}
                  value={option.value}
                >
                  {option.label}
                </option>
              ))}
            </select>
          </div>

          <div className="inventory-stock__filter">
            <SlidersHorizontal size={15} />

            <select
              value={status}
              onChange={(event) =>
                setStatus(event.target.value)
              }
              aria-label="Filter by stock status"
            >
              {STOCK_STATUS_OPTIONS.map((option) => (
                <option
                  key={option.value}
                  value={option.value}
                >
                  {option.label}
                </option>
              ))}
            </select>
          </div>

          <div className="inventory-stock__filter">
            <Warehouse size={15} />

            <select
              value={warehouse}
              onChange={(event) =>
                setWarehouse(event.target.value)
              }
              aria-label="Filter by warehouse"
            >
              <option value="all">All Warehouses</option>

              {warehouses.map((item) => (
                <option key={item.id} value={item.id}>
                  {item.name}
                </option>
              ))}
            </select>
          </div>

          {hasFilters && (
            <button
              type="button"
              className="inventory-stock__reset"
              onClick={handleReset}
            >
              Reset
            </button>
          )}
        </section>

        {/* ------------------------------------------------
            STOCK TABLE
        ------------------------------------------------ */}

        <section className="inventory-stock__table-card">
          <div className="inventory-stock__table-header">
            <div>
              <span className="inventory-stock__eyebrow">
                Stock Register
              </span>

              <h2>Current Stock</h2>
            </div>

            <div className="inventory-stock__table-meta">
              {filteredItems.length} records
            </div>
          </div>

          {loading ? (
            <div className="inventory-stock__loading">
              <RefreshCw
                size={18}
                className="inventory-stock__loading-icon"
              />

              <span>Loading inventory...</span>
            </div>
          ) : filteredItems.length === 0 ? (
            <div className="inventory-stock__empty">
              <div className="inventory-stock__empty-icon">
                <Boxes size={21} />
              </div>

              <h3>No stock records yet</h3>

              <p>
                Inventory stock will appear here once products
                are received and recorded in the system.
              </p>

              <Button
                variant="primary"
                onClick={() =>
                  router.push(
                    "/procurement/goods-receipts"
                  )
                }
              >
                Receive Stock
              </Button>
            </div>
          ) : (
            <div className="inventory-stock__table-wrap">
              <table className="inventory-stock__table">
                <thead>
                  <tr>
                    <th>Product</th>
                    <th>SKU</th>
                    <th>Category</th>
                    <th>Warehouse</th>
                    <th>Available</th>
                    <th>Reserved</th>
                    <th>Unit</th>
                    <th>Status</th>
                  </tr>
                </thead>

                <tbody>
                  {filteredItems.map((item) => (
                    <tr key={item.id}>
                      <td>
                        <div className="inventory-stock__product">
                          <strong>{item.name}</strong>

                          {item.variant && (
                            <span>{item.variant}</span>
                          )}
                        </div>
                      </td>

                      <td>{item.sku || "—"}</td>

                      <td>
                        {item.categoryLabel ||
                          item.category ||
                          "—"}
                      </td>

                      <td>
                        {item.warehouseName || "—"}
                      </td>

                      <td>
                        <strong>
                          {item.availableQuantity ?? 0}
                        </strong>
                      </td>

                      <td>
                        {item.reservedQuantity ?? 0}
                      </td>

                      <td>{item.unit || "—"}</td>

                      <td>
                        <span
                          className={`inventory-stock__status inventory-stock__status--${item.status}`}
                        >
                          {item.statusLabel ||
                            item.status ||
                            "Unknown"}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </section>
      </div>
    </main>
  );
}

"use client";

import { useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import {
  Building2,
  Download,
  MapPin,
  Package,
  Plus,
  Search,
  Warehouse as WarehouseIcon,
} from "lucide-react";

import PageHeader from "@/components/ui/PageHeader";
import Button from "@/components/ui/Button";

import "./Warehouses.css";

const STATUS_OPTIONS = [
  { value: "all", label: "All Status" },
  { value: "active", label: "Active" },
  { value: "attention", label: "Attention" },
  { value: "inactive", label: "Inactive" },
];

export default function WarehousesPage() {
  const router = useRouter();

  const [search, setSearch] = useState("");
  const [status, setStatus] = useState("all");
  const [loading] = useState(false);

  /*
   * Backend-ready.
   * Real warehouse records will come from the API later.
   */
  const warehouses = [];

  const filteredWarehouses = useMemo(() => {
    const searchValue = search.trim().toLowerCase();

    return warehouses.filter((warehouse) => {
      const matchesSearch =
        !searchValue ||
        warehouse.name?.toLowerCase().includes(searchValue) ||
        warehouse.code?.toLowerCase().includes(searchValue) ||
        warehouse.location?.toLowerCase().includes(searchValue);

      const matchesStatus =
        status === "all" || warehouse.status === status;

      return matchesSearch && matchesStatus;
    });
  }, [warehouses, search, status]);

  const totalCapacity = warehouses.reduce(
    (sum, warehouse) => sum + (warehouse.capacity || 0),
    0
  );

  const usedCapacity = warehouses.reduce(
    (sum, warehouse) => sum + (warehouse.usedCapacity || 0),
    0
  );

  const activeWarehouses = warehouses.filter(
    (warehouse) => warehouse.status === "active"
  ).length;

  const attentionWarehouses = warehouses.filter(
    (warehouse) => warehouse.status === "attention"
  ).length;

  const handleAddWarehouse = () => {
    /*
     * Warehouse creation form/API will be connected later.
     */
    /* Backend integration pending. */
  };

  const handleExport = () => {
    /*
     * Export API will be connected later.
     */
    /* Backend integration pending. */
  };

  const handleReset = () => {
    setSearch("");
    setStatus("all");
  };

  const hasFilters = search || status !== "all";

  return (
    <main className="inventory-warehouses">
      <PageHeader
        eyebrow="Inventory"
        title="Warehouses"
        description="Manage storage facilities, warehouse locations, capacity, and inventory availability."
        action={
          <div className="inventory-warehouses__header-actions">
            <Button
              variant="secondary"
              onClick={handleExport}
              disabled={loading || warehouses.length === 0}
            >
              <Download size={15} />
              Export
            </Button>

            <Button
              variant="primary"
              onClick={handleAddWarehouse}
            >
              <Plus size={15} />
              Add Warehouse
            </Button>
          </div>
        }
      />

      <div className="inventory-warehouses__content">
        {/* ------------------------------------------------
            SUMMARY
        ------------------------------------------------ */}

        <section className="inventory-warehouses__summary">
          <div className="inventory-warehouses__summary-card">
            <div className="inventory-warehouses__summary-icon">
              <WarehouseIcon size={18} />
            </div>

            <div>
              <span>Total Warehouses</span>
              <strong>{warehouses.length}</strong>
            </div>
          </div>

          <div className="inventory-warehouses__summary-card">
            <div className="inventory-warehouses__summary-icon">
              <Building2 size={18} />
            </div>

            <div>
              <span>Active</span>
              <strong>{activeWarehouses}</strong>
            </div>
          </div>

          <div className="inventory-warehouses__summary-card">
            <div className="inventory-warehouses__summary-icon">
              <MapPin size={18} />
            </div>

            <div>
              <span>Attention</span>
              <strong>{attentionWarehouses}</strong>
            </div>
          </div>

          <div className="inventory-warehouses__summary-card">
            <div className="inventory-warehouses__summary-icon">
              <Package size={18} />
            </div>

            <div>
              <span>Capacity Used</span>
              <strong>
                {totalCapacity > 0
                  ? `${Math.round(
                      (usedCapacity / totalCapacity) * 100
                    )}%`
                  : "0%"}
              </strong>
            </div>
          </div>
        </section>

        {/* ------------------------------------------------
            FILTERS
        ------------------------------------------------ */}

        <section className="inventory-warehouses__filters">
          <div className="inventory-warehouses__search">
            <Search size={16} />

            <input
              type="search"
              value={search}
              onChange={(event) =>
                setSearch(event.target.value)
              }
              placeholder="Search warehouse, code, location..."
              aria-label="Search warehouses"
            />
          </div>

          <div className="inventory-warehouses__select">
            <select
              value={status}
              onChange={(event) =>
                setStatus(event.target.value)
              }
              aria-label="Filter warehouse status"
            >
              {STATUS_OPTIONS.map((option) => (
                <option
                  key={option.value}
                  value={option.value}
                >
                  {option.label}
                </option>
              ))}
            </select>
          </div>

          {hasFilters && (
            <button
              type="button"
              className="inventory-warehouses__reset"
              onClick={handleReset}
            >
              Reset
            </button>
          )}
        </section>

        {/* ------------------------------------------------
            WAREHOUSE LIST
        ------------------------------------------------ */}

        <section className="inventory-warehouses__card">
          <div className="inventory-warehouses__card-header">
            <div>
              <span className="inventory-warehouses__eyebrow">
                Warehouse Master
              </span>

              <h2>Storage Locations</h2>
            </div>

            <span className="inventory-warehouses__count">
              {filteredWarehouses.length} records
            </span>
          </div>

          {loading ? (
            <div className="inventory-warehouses__loading">
              Loading warehouses...
            </div>
          ) : filteredWarehouses.length === 0 ? (
            <div className="inventory-warehouses__empty">
              <div className="inventory-warehouses__empty-icon">
                <WarehouseIcon size={22} />
              </div>

              <h3>No warehouses configured</h3>

              <p>
                Warehouse locations will appear here once they
                are created in the system.
              </p>

              <Button
                variant="primary"
                onClick={handleAddWarehouse}
              >
                <Plus size={15} />
                Add Warehouse
              </Button>
            </div>
          ) : (
            <div className="inventory-warehouses__grid">
              {filteredWarehouses.map((warehouse) => {
                const capacity =
                  warehouse.capacity || 0;

                const used =
                  warehouse.usedCapacity || 0;

                const utilization =
                  capacity > 0
                    ? Math.min(
                        100,
                        Math.round(
                          (used / capacity) * 100
                        )
                      )
                    : 0;

                return (
                  <article
                    className="inventory-warehouses__item"
                    key={warehouse.id}
                  >
                    <div className="inventory-warehouses__item-top">
                      <div className="inventory-warehouses__item-icon">
                        <WarehouseIcon size={18} />
                      </div>

                      <span
                        className={`inventory-warehouses__status inventory-warehouses__status--${warehouse.status}`}
                      >
                        {warehouse.statusLabel ||
                          warehouse.status}
                      </span>
                    </div>

                    <h3>{warehouse.name}</h3>

                    <div className="inventory-warehouses__code">
                      {warehouse.code || "—"}
                    </div>

                    <div className="inventory-warehouses__location">
                      <MapPin size={14} />
                      <span>
                        {warehouse.location || "Location not set"}
                      </span>
                    </div>

                    <div className="inventory-warehouses__stats">
                      <div>
                        <span>Items</span>
                        <strong>
                          {warehouse.items || 0}
                        </strong>
                      </div>

                      <div>
                        <span>Quantity</span>
                        <strong>
                          {warehouse.quantity || 0}
                        </strong>
                      </div>
                    </div>

                    <div className="inventory-warehouses__capacity">
                      <div className="inventory-warehouses__capacity-header">
                        <span>Capacity</span>
                        <strong>
                          {utilization}%
                        </strong>
                      </div>

                      <div className="inventory-warehouses__progress">
                        <span
                          style={{
                            width: `${utilization}%`,
                          }}
                        />
                      </div>
                    </div>
                  </article>
                );
              })}
            </div>
          )}
        </section>
      </div>
    </main>
  );
}

