  },
  {
    id: "quotation",
    label: "Quotation",
    description: "Prepare a customer quotation",
    group: "Business",
    icon: FileText,
    shortcut: "QT",
    href: "/sales/orders",
  },
  {
    id: "product",
    label: "Product",
    description: "Create a garment, fabric or accessory",
    group: "Business",
    icon: Package,
    shortcut: "PR",
    href: "/products/new",
